// simplified only where the inference machinery (`EffectFunction`, `NoInfer`,
// the seed-value overloads) is irrelevant here. Nothing is loosened.
export type Accessor<T> = () => T;

export declare function untrack<T>(fn: Accessor<T>): T;
export declare function createEffect(fn: () => void): void;
export declare function createRenderEffect(fn: () => void): void;
export declare function createMemo<T>(fn: () => T): Accessor<T>;
export declare function createRoot<T>(fn: (dispose: () => void) => T): T;
export declare function createSignal<T>(value: T): [Accessor<T>, (next: T) => T];
export declare function mergeProps(...sources: unknown[]): unknown;
export declare function onCleanup<T extends () => unknown>(fn: T): T;
